import{_ as s,c as e,o as i,ag as t}from"./chunks/framework.C7v41-tM.js";const k=JSON.parse('{"title":"uv 锁文件：本地能跑，CI 为什么还会失败","description":"","frontmatter":{},"headers":[],"relativePath":"notes/uv-lock-ci.md","filePath":"notes/uv-lock-ci.md","lastUpdated":null}'),n={name:"notes/uv-lock-ci.md"};function l(o,a,r,h,p,c){return i(),e("div",null,[...a[0]||(a[0]=[t(`<h1 id="uv-锁文件-本地能跑-ci-为什么还会失败" tabindex="-1">uv 锁文件：本地能跑，CI 为什么还会失败 <a class="header-anchor" href="#uv-锁文件-本地能跑-ci-为什么还会失败" aria-label="Permalink to &quot;uv 锁文件：本地能跑，CI 为什么还会失败&quot;">​</a></h1><p>先区分“依赖需求”“解析结果”和“本机环境”。术语定义见 <a href="https://github.com/lixudong1649/jdp-wiki/blob/main/content/terms/lockfile.md" target="_blank" rel="noreferrer">锁文件</a>，本文只讲排障步骤。</p><h2 id="三份内容不能混为一谈" tabindex="-1">三份内容不能混为一谈 <a class="header-anchor" href="#三份内容不能混为一谈" aria-label="Permalink to &quot;三份内容不能混为一谈&quot;">​</a></h2><p><code>pyproject.toml</code> 声明需求，<code>uv.lock</code> 固定解析结果，<code>.venv/</code> 是当前机器安装好的环境。只在本机手工安装一个包，别人拉代码后不一定能复现。</p><h2 id="一次检查的顺序" tabindex="-1">一次检查的顺序 <a class="header-anchor" href="#一次检查的顺序" aria-label="Permalink to &quot;一次检查的顺序&quot;">​</a></h2><p>在项目根目录按目的选择命令，不必全部运行：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lock</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --check</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sync</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --locked</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --locked</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;import sys; print(sys.version)&quot;</span></span></code></pre></div><p>第一条检查声明与锁文件的一致性；后两条在需要改锁时失败。<code>--frozen</code> 跳过一致性检查，适合特定构建分层，不能替代 CI 的一致性校验。</p><p>如果刚改了依赖，先用 <code>uv lock</code> 生成解析结果，审查变化，再把声明与锁文件一起提交。升级和冲突合并也先看需求，不为消除冲突直接删锁文件。</p><h2 id="还会有哪些差异" tabindex="-1">还会有哪些差异 <a class="header-anchor" href="#还会有哪些差异" aria-label="Permalink to &quot;还会有哪些差异&quot;">​</a></h2><p>锁文件不锁操作系统、驱动和外部服务。确认 Python 版本、依赖组、extras 及平台条件，再比较本地与 CI。同步可能移除不属于目标依赖集合的包，项目依赖应通过项目配置维护。</p><p>参考：<a href="https://docs.astral.sh/uv/concepts/projects/sync/" target="_blank" rel="noreferrer">uv 锁定与同步</a>。命令语义复核：2026-10-14；本文未声称对任意项目实际执行上述命令。</p>`,12)])])}const u=s(n,[["render",l]]);export{k as __pageData,u as default};
